{
  "story": "A bill travels from initial proposal through committee review, floor debate, and presidential approval to finally become federal law.",
  "aha": {
    "stateId": "presidential",
    "observation": "The President signs the bill, or overrides a veto, successfully enacting the proposal into law."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Legislative Step",
      "options": [
        "Introduction",
        "Committee",
        "Floor Debate",
        "Presidential Action"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "US Legislative Process",
        "regions": [
          {
            "id": "reg_house",
            "label": "House of Representatives",
            "values": ["Drafting", "Introduction"]
          },
          {
            "id": "reg_committee",
            "label": "Congressional Committee",
            "values": ["Hearings", "Markup"]
          },
          {
            "id": "reg_floor",
            "label": "Chamber Floors",
            "values": ["Debate", "Roll Call Vote"]
          },
          {
            "id": "reg_president",
            "label": "Executive Branch",
            "values": ["Signature", "Veto Override"]
          }
        ],
        "states": [
          {
            "id": "intro",
            "label": "1. Introduction",
            "short": "Draft",
            "sentence": "A representative introduces the bill.",
            "why": "All legislative ideas must start with a formal proposal.",
            "active": ["reg_house"],
            "calloutRegion": "reg_house",
            "readouts": [
              {
                "id": "stage",
                "label": "Current Stage",
                "value": "Introduction"
              }
            ]
          },
          {
            "id": "committee",
            "label": "2. Committee",
            "short": "Review",
            "sentence": "Specialized committees study, amend, and vote on the bill.",
            "why": "Committees provide expert vetting before general debate.",
            "active": ["reg_committee"],
            "calloutRegion": "reg_committee",
            "readouts": [
              {
                "id": "stage",
                "label": "Current Stage",
                "value": "Committee Review"
              }
            ]
          },
          {
            "id": "floor",
            "label": "3. Floor Debate",
            "short": "Vote",
            "sentence": "Chambers debate the bill and hold a recorded vote.",
            "why": "A majority approval sends the measure to the executive.",
            "active": ["reg_floor"],
            "calloutRegion": "reg_floor",
            "readouts": [
              {
                "id": "stage",
                "label": "Current Stage",
                "value": "Floor Vote"
              }
            ]
          },
          {
            "id": "presidential",
            "label": "4. President",
            "short": "Law",
            "sentence": "The President signs the bill into official law.",
            "why": "Executive signature completes the legislative journey.",
            "active": ["reg_president"],
            "calloutRegion": "reg_president",
            "readouts": [
              {
                "id": "stage",
                "label": "Current Stage",
                "value": "Enacted"
              }
            ]
          }
        ]
      }
    ]
  }
}
